{
  "findings": [
    {
      "check_id": "CKV2_AWS_11",
      "title": "Ensure VPC flow logging is enabled in all VPCs",
      "resource": "aws_vpc.changeme_aws_vpc_simple",
      "severity": "MEDIUM",
      "explanation": "The VPC does not have flow logs enabled, which prevents visibility into network traffic for security monitoring and incident investigation."
    }
  ],
  "patched_code": "resource "aws_vpc" "changeme_aws_vpc_simple" {
  cidr_block = "10.1.0.0/16"
}

resource "aws_cloudwatch_log_group" "vpc_flow_logs" {
  name              = "/aws/vpc/${aws_vpc.changeme_aws_vpc_simple.id}/flow-logs"
  retention_in_days = 30
}

resource "aws_iam_role" "vpc_flow_logs_role" {
  name = "vpc-flow-logs-role-${aws_vpc.changeme_aws_vpc_simple.id}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "vpc_flow_logs_policy" {
  name = "vpc-flow-logs-policy-${aws_vpc.changeme_aws_vpc_simple.id}"
  role = aws_iam_role.vpc_flow_logs_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_flow_log" "example" {
  vpc_id               = aws_vpc.changeme_aws_vpc_simple.id
  traffic_type         = "ALL"
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.vpc_flow_logs.arn
  iam_role_arn         = aws_iam_role.vpc_flow_logs_role.arn
}",
  "fix_summary": "Added CloudWatch Log Group, IAM Role, and IAM Policy to support VPC Flow Logs, then attached an aws_flow_log resource to the existing VPC to enable network traffic logging."
}
